window.AzubaImageUpload=(function(){async function m(t,r){if(!r)throw new Error("ImgBB isn't configured (no API key).");const a=new FormData;a.append("image",t);let i;try{i=await fetch(`https://api.imgbb.com/1/upload?key=${encodeURIComponent(r)}`,{method:"POST",body:a})}catch{throw new Error("Couldn't reach ImgBB (it may be down, or something on this network/browser is blocking it).")}const e=await i.json();if(e&&e.success&&e.data&&e.data.url)return e.data.url;throw new Error("ImgBB upload failed: "+(e&&e.error&&e.error.message?e.error.message:"unknown error"))}async function s(t,r,a){if(!r||!a)throw new Error("ImageKit isn't fully configured (need Public Key + URL Endpoint).");const i=await fetch("/api/imagekit-auth",{method:"POST"}),e=await i.json();if(!i.ok||!e.ok)throw new Error(e.error||"Couldn't prepare the ImageKit upload.");const o=new FormData;o.append("file",t),o.append("fileName",t.name||`upload-${Date.now()}.jpg`),o.append("publicKey",r),o.append("token",e.token),o.append("expire",String(e.expire)),o.append("signature",e.signature),o.append("useUniqueFileName","true");let u;try{u=await fetch("https://upload.imagekit.io/api/v1/files/upload",{method:"POST",body:o})}catch{throw new Error("Couldn't reach ImageKit (it may be down, or something on this network/browser is blocking it).")}const n=await u.json();if(u.ok&&n&&n.url)return n.url;throw new Error("ImageKit upload failed: "+(n&&n.message?n.message:"unknown error"))}function p(t,r){return t==="imgbb"?!!r.imgbbKey:t==="imagekit"?!!(r.imagekitPublicKey&&r.imagekitUrlEndpoint):!1}async function d(t,r,a){if(t==="imgbb")return m(r,a.imgbbKey);if(t==="imagekit")return s(r,a.imagekitPublicKey,a.imagekitUrlEndpoint);throw new Error("Unknown image provider: "+t)}async function c(t,r){const a=r.activeProvider==="imagekit"?"imagekit":"imgbb",i=a==="imgbb"?"imagekit":"imgbb";try{return await d(a,t,r)}catch(e){if(!p(i,r))throw e;try{return await d(i,t,r)}catch(o){throw new Error(`${e.message} (backup provider also failed: ${o.message})`)}}}return{upload:c,uploadToImgbb:m,uploadToImageKit:s}})();
